				\begin{document}$${Y}^{*}= {\beta }_{1}\mathrm{MO}2+{\beta }_{2}\mathrm{MO}3+{\beta }_{3}\mathrm{MO}4+{\beta }_{4}\mathrm{MO}5+{\beta }_{5}\mathrm{SC}2+{\beta }_{6}\mathrm{SC}3+{\beta }_{7}\mathrm{SC}4+{\beta }_{8}\mathrm{SC}5+{\beta }_{9}\mathrm{UA}2+{\beta }_{10}\mathrm{UA}3+{\beta }_{11}\mathrm{UA}4+{\beta }_{12}\mathrm{UA}5+{\beta }_{13}\mathrm{PD}2+{\beta }_{14}\mathrm{PD}3+{\beta }_{15}\mathrm{PD}4+{\beta }_{16}\mathrm{PD}5+{\beta }_{17}\mathrm{AD}2+{\beta }_{18}\mathrm{AD}3+{\beta }_{19}\mathrm{AD}4+{\beta }_{20}\mathrm{AD}5+u,$$\end{document}Y∗=β1MO2+β2MO3+β3MO4+β4MO5+β5SC2+β6SC3+β7SC4+β8SC5+β9UA2+β10UA3+β11UA4+β12UA5+β13PD2+β14PD3+β15PD4+β16PD5+β17AD2+β18AD3+β19AD4+β20AD5+u,\documentclass[12pt]{minimal}
